import{_ as r,o as e,c as a,a2 as d}from"./chunks/framework.oeh4wjV1.js";const p=JSON.parse('{"title":"Food, Objects, and Transportation Beyond Marvel","description":"","frontmatter":{},"headers":[],"relativePath":"research/everyday-life/objects.md","filePath":"research/everyday-life/objects.md","lastUpdated":1792425987000}'),n={name:"research/everyday-life/objects.md"};function i(o,t,c,l,s,h){return e(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="food-objects-and-transportation-beyond-marvel" tabindex="-1">Food, Objects, and Transportation Beyond Marvel <a class="header-anchor" href="#food-objects-and-transportation-beyond-marvel" aria-label="Permalink to &quot;Food, Objects, and Transportation Beyond Marvel&quot;">​</a></h1><p>Meals, tools, household objects, games, and vehicles, checked October 19, 2026. These are ordinary things that can become ridiculous game pieces without needing to be characters. The <a href="./marvel.html">Marvel page</a> contains the bagel, hot dog cart, camera, newspaper, news helicopter, ferry, and subway.</p><p><strong>Direct</strong> entries have a strong everyday-life premise; <strong>Setting</strong> entries have a more historical or fantastical visual context. Animated objects, disguised machines, and other explicit exceptions are in <a href="./almost-matches.html#food-and-objects">Almost matches</a>. Vehicles retain their normal crew and animation rules.</p><p><a href="./../everyday-life.html">Back to the full catalogue</a>.</p><h2 id="food-and-objects" tabindex="-1">Food and objects <a class="header-anchor" href="#food-and-objects" aria-label="Permalink to &quot;Food and objects&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Card and printing</th><th>Actual type</th><th>Fit</th><th>Why consider it / qualification</th></tr></thead><tbody><tr><td><a href="https://scryfall.com/card/who/170/aces-baseball-bat" target="_blank" rel="noreferrer">Ace&#39;s Baseball Bat</a> · WHO 170</td><td>Legendary Artifact — Equipment</td><td>Direct</td><td>A real sporting object belonging to a Doctor Who character.</td></tr><tr><td><a href="https://scryfall.com/card/tmt/57/anchovy-&amp;-banana-pizza" target="_blank" rel="noreferrer">Anchovy &amp; Banana Pizza</a> · TMT 57</td><td>Artifact — Food</td><td>Direct</td><td>Strange toppings are still food. A TMNT pizza with an ordinary takeout premise.</td></tr><tr><td><a href="https://scryfall.com/card/tmc/36/arcade-cabinet" target="_blank" rel="noreferrer">Arcade Cabinet</a> · TMC 36</td><td>Artifact</td><td>Direct</td><td>An arcade game as an artifact; strong everyday recreation material.</td></tr><tr><td><a href="https://scryfall.com/card/mmq/288/bargaining-table" target="_blank" rel="noreferrer">Bargaining Table</a> · MMQ 288</td><td>Artifact</td><td>Setting</td><td>An ordinary table for doing business, with older fantasy-era artwork.</td></tr><tr><td><a href="https://scryfall.com/card/dsk/209/baseball-bat" target="_blank" rel="noreferrer">Baseball Bat</a> · DSK 209</td><td>Artifact — Equipment</td><td>Direct</td><td>A recognizable ordinary sporting object, even when used as a weapon.</td></tr><tr><td><a href="https://scryfall.com/card/dsk/243/bear-trap" target="_blank" rel="noreferrer">Bear Trap</a> · DSK 243</td><td>Artifact</td><td>Setting</td><td>An ordinary mechanical trap in a horror setting; more outdoors/security than city leisure.</td></tr><tr><td><a href="https://scryfall.com/card/inr/255/boarded-window" target="_blank" rel="noreferrer">Boarded Window</a> · INR 255</td><td>Artifact</td><td>Direct</td><td>An ordinary household fixture in a horror setting.</td></tr><tr><td><a href="https://scryfall.com/card/inr/256/butchers-cleaver" target="_blank" rel="noreferrer">Butcher&#39;s Cleaver</a> · INR 256</td><td>Artifact — Equipment</td><td>Setting</td><td>An ordinary kitchen/work tool, with a Gothic-horror setting.</td></tr><tr><td><a href="https://scryfall.com/card/mkm/43/candlestick" target="_blank" rel="noreferrer">Candlestick</a> · MKM 43</td><td>Artifact — Clue Equipment</td><td>Direct</td><td>An ordinary household object with a murder-mystery role.</td></tr><tr><td><a href="https://scryfall.com/card/woe/243/candy-trail" target="_blank" rel="noreferrer">Candy Trail</a> · WOE 243</td><td>Artifact — Food Clue</td><td>Setting</td><td>Ordinary sweets arranged as a fairy-tale trail; a strong food object with a setting caveat.</td></tr><tr><td><a href="https://scryfall.com/card/blb/7/carrot-cake" target="_blank" rel="noreferrer">Carrot Cake</a> · BLB 7</td><td>Artifact — Food</td><td>Direct</td><td>An ordinary dessert. Rabbit tokens are game effects, not a requirement that the cake be a magical character.</td></tr><tr><td><a href="https://scryfall.com/card/snc/235/cement-shoes" target="_blank" rel="noreferrer">Cement Shoes</a> · SNC 235</td><td>Artifact — Equipment</td><td>Direct</td><td>A crime-story object and dark urban joke, not normal footwear.</td></tr><tr><td><a href="https://scryfall.com/card/dsk/128/chainsaw" target="_blank" rel="noreferrer">Chainsaw</a> · DSK 128</td><td>Artifact — Equipment</td><td>Direct</td><td>A modern power tool. Horror framing affects tone, not whether chainsaws are ordinary objects.</td></tr><tr><td><a href="https://scryfall.com/card/snc/8/citizens-crowbar" target="_blank" rel="noreferrer">Citizen&#39;s Crowbar</a> · SNC 8</td><td>Artifact — Equipment</td><td>Direct</td><td>A crowbar and an ordinary Citizen token; one of the strongest non-Marvel city tools.</td></tr><tr><td><a href="https://scryfall.com/card/snc/142/couriers-briefcase" target="_blank" rel="noreferrer">Courier&#39;s Briefcase</a> · SNC 142</td><td>Artifact — Treasure</td><td>Direct</td><td>Work luggage and a courier association; actually an Artifact — Treasure.</td></tr><tr><td><a href="https://scryfall.com/card/tmt/173/everything-pizza" target="_blank" rel="noreferrer">Everything Pizza</a> · TMT 173</td><td>Artifact — Food</td><td>Direct</td><td>Takeout as an artifact. The toppings can be absurd without making the meal a superhero.</td></tr><tr><td><a href="https://scryfall.com/card/fdn/724/expedition-map" target="_blank" rel="noreferrer">Expedition Map</a> · FDN 724</td><td>Artifact</td><td>Setting</td><td>A map is an ordinary object; the expedition imagery may be far from city life.</td></tr><tr><td><a href="https://scryfall.com/card/ltc/11/field-tested-frying-pan" target="_blank" rel="noreferrer">Field-Tested Frying Pan</a> · LTC 11</td><td>Artifact — Equipment</td><td>Setting</td><td>Cooking equipment put to another use; a hobbit-associated printing rather than a modern kitchen.</td></tr><tr><td><a href="https://scryfall.com/card/afr/244/fifty-feet-of-rope" target="_blank" rel="noreferrer">Fifty Feet of Rope</a> · AFR 244</td><td>Artifact</td><td>Setting</td><td>A very ordinary length of rope, presented as adventuring equipment.</td></tr><tr><td><a href="https://scryfall.com/card/otj/242/gold-pan" target="_blank" rel="noreferrer">Gold Pan</a> · OTJ 242</td><td>Artifact — Equipment</td><td>Setting</td><td>An ordinary prospecting tool, with a frontier rather than city setting.</td></tr><tr><td><a href="https://scryfall.com/card/isd/225/graveyard-shovel" target="_blank" rel="noreferrer">Graveyard Shovel</a> · ISD 225</td><td>Artifact</td><td>Setting</td><td>An ordinary shovel with a cemetery job.</td></tr><tr><td><a href="https://scryfall.com/card/tmt/116/guac-&amp;-marshmallow-pizza" target="_blank" rel="noreferrer">Guac &amp; Marshmallow Pizza</a> · TMT 116</td><td>Artifact — Food</td><td>Direct</td><td>Another ordinary food object with intentionally questionable toppings.</td></tr><tr><td><a href="https://scryfall.com/card/blb/175/heaped-harvest" target="_blank" rel="noreferrer">Heaped Harvest</a> · BLB 175</td><td>Artifact — Food</td><td>Setting</td><td>Ordinary harvested food; rural rather than modern-city presentation.</td></tr><tr><td><a href="https://scryfall.com/card/ltr/242/inherited-envelope" target="_blank" rel="noreferrer">Inherited Envelope</a> · LTR 242</td><td>Artifact</td><td>Setting</td><td>An ordinary letter/envelope from The Lord of the Rings, in a period-fantasy setting.</td></tr><tr><td><a href="https://scryfall.com/card/fin/259/instant-ramen" target="_blank" rel="noreferrer">Instant Ramen</a> · FIN 259</td><td>Artifact — Food</td><td>Direct</td><td>Exactly the contemporary cheap-meal object the theme wants; a Final Fantasy Food artifact.</td></tr><tr><td><a href="https://scryfall.com/card/cmm/956/investigators-journal" target="_blank" rel="noreferrer">Investigator&#39;s Journal</a> · CMM 956</td><td>Artifact — Book Clue</td><td>Setting</td><td>A detective&#39;s notebook; useful ordinary paperwork in a fantasy-city investigation.</td></tr><tr><td><a href="https://scryfall.com/card/snc/111/jackhammer" target="_blank" rel="noreferrer">Jackhammer</a> · SNC 111</td><td>Artifact — Equipment</td><td>Direct</td><td>Construction equipment from New Capenna; particularly good alongside repair crews.</td></tr><tr><td><a href="https://scryfall.com/card/dsk/251/keys-to-the-house" target="_blank" rel="noreferrer">Keys to the House</a> · DSK 251</td><td>Artifact</td><td>Direct</td><td>House keys, even though the house in the source set is a terrible place to live.</td></tr><tr><td><a href="https://scryfall.com/card/mkm/134/knife" target="_blank" rel="noreferrer">Knife</a> · MKM 134</td><td>Artifact — Clue Equipment</td><td>Direct</td><td>A plainly named everyday utensil/tool, presented as Clue Equipment.</td></tr><tr><td><a href="https://scryfall.com/card/cmm/397/letter-of-acceptance" target="_blank" rel="noreferrer">Letter of Acceptance</a> · CMM 397</td><td>Artifact</td><td>Setting</td><td>School-admission paperwork is mundane; this school happens to be magical.</td></tr><tr><td><a href="https://scryfall.com/card/tmc/130/manhole-cover" target="_blank" rel="noreferrer">Manhole Cover</a> · TMC 130</td><td>Artifact</td><td>Direct</td><td>A mundane piece of city infrastructure, used as an improvised shield.</td></tr><tr><td><a href="https://scryfall.com/card/exo/133/medicine-bag" target="_blank" rel="noreferrer">Medicine Bag</a> · EXO 133</td><td>Artifact</td><td>Setting</td><td>Medical supplies in an older fantasy setting; inspect the particular healing imagery.</td></tr><tr><td><a href="https://scryfall.com/card/dom/225/navigators-compass" target="_blank" rel="noreferrer">Navigator&#39;s Compass</a> · DOM 225</td><td>Artifact</td><td>Setting</td><td>An ordinary navigation instrument in a fantasy-adventure setting.</td></tr><tr><td><a href="https://scryfall.com/card/sld/2462/nuka-cola-vending-machine" target="_blank" rel="noreferrer">Nuka-Cola Vending Machine</a> · SLD 2462</td><td>Artifact</td><td>Setting</td><td>An ordinary vending-machine premise with Fallout branding. This selected printing shows a Sunset Sarsaparilla machine; the rules name remains Nuka-Cola Vending Machine. This printing&#39;s alternate title: Sunset Sarsaparilla Machine.</td></tr><tr><td><a href="https://scryfall.com/card/tmt/176/omni-cheese-pizza" target="_blank" rel="noreferrer">Omni-Cheese Pizza</a> · TMT 176</td><td>Artifact — Food</td><td>Direct</td><td>A straightforward pizza option for a city food packet.</td></tr><tr><td><a href="https://scryfall.com/card/lci/70/pirate-hat" target="_blank" rel="noreferrer">Pirate Hat</a> · LCI 70</td><td>Artifact — Equipment</td><td>Setting</td><td>An ordinary hat from a period/pirate setting; potentially costume-party material.</td></tr><tr><td><a href="https://scryfall.com/card/dde/22/puppet-strings" target="_blank" rel="noreferrer">Puppet Strings</a> · DDE 22</td><td>Artifact</td><td>Setting</td><td>Ordinary puppet equipment; the rules effect can represent pulling strings figuratively.</td></tr><tr><td><a href="https://scryfall.com/card/aer/173/renegade-map" target="_blank" rel="noreferrer">Renegade Map</a> · AER 173</td><td>Artifact</td><td>Setting</td><td>A map, with Kaladesh&#39;s industrial rather than modern-Earth surroundings.</td></tr><tr><td><a href="https://scryfall.com/card/jmp/479/rogues-gloves" target="_blank" rel="noreferrer">Rogue&#39;s Gloves</a> · JMP 479</td><td>Artifact — Equipment</td><td>Setting</td><td>A pair of gloves with a fantasy-thief association.</td></tr><tr><td><a href="https://scryfall.com/card/mkm/173/rope" target="_blank" rel="noreferrer">Rope</a> · MKM 173</td><td>Artifact — Clue Equipment</td><td>Direct</td><td>A mundane length of rope used as Clue Equipment.</td></tr><tr><td><a href="https://scryfall.com/card/dsk/254/saw" target="_blank" rel="noreferrer">Saw</a> · DSK 254</td><td>Artifact — Equipment</td><td>Direct</td><td>A household/workshop tool with a horror-set presentation.</td></tr><tr><td><a href="https://scryfall.com/card/ddq/32/sharpened-pitchfork" target="_blank" rel="noreferrer">Sharpened Pitchfork</a> · DDQ 32</td><td>Artifact — Equipment</td><td>Setting</td><td>Farm equipment repurposed for trouble; rural rather than urban.</td></tr><tr><td><a href="https://scryfall.com/card/tmt/178/skateboard" target="_blank" rel="noreferrer">Skateboard</a> · TMT 178</td><td>Artifact — Equipment</td><td>Direct</td><td>Street transport and recreation; particularly appropriate to a modern-city packet.</td></tr><tr><td><a href="https://scryfall.com/card/soi/263/skeleton-key" target="_blank" rel="noreferrer">Skeleton Key</a> · SOI 263</td><td>Artifact — Equipment</td><td>Setting</td><td>A physical key with a sinister name; a good locksmith or household object candidate.</td></tr><tr><td><a href="https://scryfall.com/card/znr/254/spare-supplies" target="_blank" rel="noreferrer">Spare Supplies</a> · ZNR 254</td><td>Artifact</td><td>Setting</td><td>A package of useful everyday equipment, with fantasy-travel context.</td></tr><tr><td><a href="https://scryfall.com/card/tmt/109/spicy-oatmeal-pizza" target="_blank" rel="noreferrer">Spicy Oatmeal Pizza</a> · TMT 109</td><td>Artifact — Food</td><td>Direct</td><td>A terrible-sounding dinner is still a mundane dinner.</td></tr><tr><td><a href="https://scryfall.com/card/eld/234/spinning-wheel" target="_blank" rel="noreferrer">Spinning Wheel</a> · ELD 234</td><td>Artifact</td><td>Setting</td><td>Ordinary textile equipment with fairy-tale associations.</td></tr><tr><td><a href="https://scryfall.com/card/ecl/260/springleaf-drum" target="_blank" rel="noreferrer">Springleaf Drum</a> · ECL 260</td><td>Artifact</td><td>Setting</td><td>A musical instrument in a fantasy setting.</td></tr><tr><td><a href="https://scryfall.com/card/tmp/309/squees-toy" target="_blank" rel="noreferrer">Squee&#39;s Toy</a> · TMP 309</td><td>Artifact</td><td>Setting</td><td>An ordinary toy belonging to a goblin; the owner and art are the setting caveat.</td></tr><tr><td><a href="https://scryfall.com/card/bro/250/supply-drop" target="_blank" rel="noreferrer">Supply Drop</a> · BRO 250</td><td>Artifact</td><td>Setting</td><td>A delivery of equipment; military/fantasy context rather than an ordinary doorstep parcel.</td></tr><tr><td><a href="https://scryfall.com/card/woe/253/three-bowls-of-porridge" target="_blank" rel="noreferrer">Three Bowls of Porridge</a> · WOE 253</td><td>Artifact — Food</td><td>Setting</td><td>Ordinary breakfast from a fairy-tale setting.</td></tr><tr><td><a href="https://scryfall.com/card/zen/209/trusty-machete" target="_blank" rel="noreferrer">Trusty Machete</a> · ZEN 209</td><td>Artifact — Equipment</td><td>Setting</td><td>A real tool with an outdoors/adventure presentation.</td></tr><tr><td><a href="https://scryfall.com/card/znr/256/utility-knife" target="_blank" rel="noreferrer">Utility Knife</a> · ZNR 256</td><td>Artifact — Equipment</td><td>Setting</td><td>A plain practical tool with fantasy-adventuring context.</td></tr><tr><td><a href="https://scryfall.com/card/tmc/106/wooden-cane" target="_blank" rel="noreferrer">Wooden Cane</a> · TMC 106</td><td>Artifact — Equipment</td><td>Direct</td><td>An ordinary walking stick. Its entry ability creates a Mutant token, so the resulting board has a less mundane element.</td></tr><tr><td><a href="https://scryfall.com/card/fin/270/world-map" target="_blank" rel="noreferrer">World Map</a> · FIN 270</td><td>Artifact</td><td>Setting</td><td>A map from Final Fantasy; ordinary object, different geography and franchise.</td></tr><tr><td><a href="https://scryfall.com/card/mkm/37/wrench" target="_blank" rel="noreferrer">Wrench</a> · MKM 37</td><td>Artifact — Clue Equipment</td><td>Direct</td><td>An ordinary tool; actual Clue Equipment, not a creature.</td></tr></tbody></table><h2 id="transportation" tabindex="-1">Transportation <a class="header-anchor" href="#transportation" aria-label="Permalink to &quot;Transportation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Card and printing</th><th>Actual type</th><th>Fit</th><th>Why consider it / qualification</th></tr></thead><tbody><tr><td><a href="https://scryfall.com/card/who/171/bessie-the-doctors-roadster" target="_blank" rel="noreferrer">Bessie, the Doctor&#39;s Roadster</a> · WHO 171</td><td>Legendary Artifact — Vehicle</td><td>Setting</td><td>An old-fashioned roadster belonging to the Doctor; the vehicle itself is recognizably mundane.</td></tr><tr><td><a href="https://scryfall.com/card/snc/139/capenna-express" target="_blank" rel="noreferrer">Capenna Express</a> · SNC 139</td><td>Artifact — Vehicle</td><td>Setting</td><td>A city train with a fantasy Art Deco design.</td></tr><tr><td><a href="https://scryfall.com/card/ncc/58/dodgy-jalopy" target="_blank" rel="noreferrer">Dodgy Jalopy</a> · NCC 58</td><td>Artifact — Vehicle</td><td>Setting</td><td>A beat-up car, ideal for the joke if the period/fantasy styling is acceptable.</td></tr><tr><td><a href="https://scryfall.com/card/snc/237/getaway-car" target="_blank" rel="noreferrer">Getaway Car</a> · SNC 237</td><td>Artifact — Vehicle</td><td>Setting</td><td>A car for ordinary criminals, with New Capenna&#39;s period city design.</td></tr><tr><td><a href="https://scryfall.com/card/snc/109/hoard-hauler" target="_blank" rel="noreferrer">Hoard Hauler</a> · SNC 109</td><td>Artifact — Vehicle</td><td>Setting</td><td>A robbery vehicle: ordinary criminal logistics, rather than superhero travel.</td></tr><tr><td><a href="https://scryfall.com/card/otj/245/mobile-homestead" target="_blank" rel="noreferrer">Mobile Homestead</a> · OTJ 245</td><td>Artifact — Vehicle</td><td>Setting</td><td>A traveling home with a frontier setting rather than a New York apartment.</td></tr><tr><td><a href="https://scryfall.com/card/snc/22/mysterious-limousine" target="_blank" rel="noreferrer">Mysterious Limousine</a> · SNC 22</td><td>Artifact — Vehicle</td><td>Setting</td><td>A recognizable civilian vehicle; the fantasy-city mystery is the qualification.</td></tr><tr><td><a href="https://scryfall.com/card/who/93/rms-titanic" target="_blank" rel="noreferrer">RMS Titanic</a> · WHO 93</td><td>Legendary Artifact — Vehicle</td><td>Setting</td><td>A real historical ship. Extremely non-mundane as a famous event, but physically an ordinary passenger liner.</td></tr><tr><td><a href="https://scryfall.com/card/ncc/84/smugglers-buggy" target="_blank" rel="noreferrer">Smuggler&#39;s Buggy</a> · NCC 84</td><td>Artifact — Vehicle</td><td>Setting</td><td>A vehicle for ordinary crime, with a stylized fantasy design.</td></tr><tr><td><a href="https://scryfall.com/card/fin/267/the-regalia" target="_blank" rel="noreferrer">The Regalia</a> · FIN 267</td><td>Legendary Artifact — Vehicle</td><td>Setting</td><td>A recognizable road car from Final Fantasy; a named crossover vehicle rather than anonymous New York transport.</td></tr><tr><td><a href="https://scryfall.com/card/snc/246/unlicensed-hearse" target="_blank" rel="noreferrer">Unlicensed Hearse</a> · SNC 246</td><td>Artifact — Vehicle</td><td>Setting</td><td>An ordinary specialized vehicle in a fantasy-city crime story.</td></tr></tbody></table>',8)])])}const m=r(n,[["render",i]]);export{p as __pageData,m as default};
